#!/bin/sh
# Build the Lecture 6 slides and export one PNG per slide for L06-light.qmd.
set -e
cd "$(dirname "$0")"
lualatex -interaction=nonstopmode -halt-on-error L06-light-slides.tex >/dev/null
OUT=../../images/L06_light
mkdir -p "$OUT"
rm -f "$OUT"/L06-slide-*.png
pdftoppm -png -scale-to-x 1920 -scale-to-y -1 L06-light-slides.pdf "$OUT/L06-slide"

# Text figures (TikZ sources generated by figures/make_figures.py)
cd figures
python3 make_figures.py
for f in fig-spectrum-sea fig-ocean-zones fig-beer-lambert; do
  lualatex -interaction=nonstopmode -halt-on-error "$f.tex" >/dev/null
  pdftoppm -png -r 200 -singlefile "$f.pdf" "../$OUT/$f"
  for e in aux log pdf; do rm -f "$f.$e"; done
done
